import{_ as t,o,c as r,a0 as a}from"./chunks/framework.Obqu-B4P.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),d={name:"explanation/architecture.md"};function c(n,e,i,s,l,u){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Ports-and-adapters over a flat <code>crates/</code> workspace. <code>cuora-core</code> is pure domain — <code>cuora://</code> refs, the redacting <code>Secret</code> newtype, the env axis, actor attribution — with no I/O. Ports are traits (<code>cuora-config</code>, <code>cuora-vault</code>, <code>cuora-deploy</code>); impls live in separate crates; <code>crates/cuora-cli</code> (package <code>cuora</code>) is the composition root that wires impls to verbs.</p><p>Design rules:</p><ul><li><strong>No <code>unsafe</code>, no async</strong> — the binary stays dependency-light and synchronous; vault impls that speak HTTP use a blocking client (<code>ureq</code>), so no runtime embeds anywhere.</li><li><strong><code>Secret</code> never exposes plaintext</strong> — no <code>Display</code>/<code>Debug</code> of the value; <code>.expose()</code> is the only way out, called at edges only (child env injection, <code>cuora env</code> exports, <code>get</code>).</li><li><strong>Stores hold ciphertext only</strong> — every vault impl encrypts client-side with age (ADR-0001); a remote vault is ciphertext over the wire <em>and</em> at rest, never a plaintext service.</li><li><strong>Ports are conformance-tested</strong> — <code>cuora-testkit</code> runs the same contract suite against every vault impl (<code>cuora-vault-age</code>, <code>cuora-vault-cf</code>): upsert/rotate/list/env-isolation semantics can&#39;t drift per backend.</li><li><strong>One ops shell</strong> — <code>cuora-ops</code> owns config load, env→vault routing, the env-pin rule, and audit emission; the CLI and the TUI are both thin front-ends over it and cannot diverge.</li></ul><table tabindex="0"><thead><tr><th>crate</th><th>layer</th><th>purpose</th></tr></thead><tbody><tr><td><code>cuora-core</code></td><td>domain</td><td>cuora domain core: cuora:// refs, redacting Secret, env axis, actor, config model — pure, no I/O</td></tr><tr><td><code>cuora-config</code></td><td>port</td><td>Config port: where cuora.toml-shaped config comes from</td></tr><tr><td><code>cuora-deploy</code></td><td>port</td><td>Deploy port: write-only push targets (sinks) for secret values — never a source</td></tr><tr><td><code>cuora-vault</code></td><td>port</td><td>Vault port: readable secret stores — get/put/rm/list/rotate, per-env; every impl stores opaque ciphertext</td></tr><tr><td><code>cuora-ops</code></td><td>ops</td><td>cuora ops I/O: config load, env/ref resolution, vault open, verb plumbing, audit emission</td></tr><tr><td><code>cuora-config-toml</code></td><td>adapter</td><td>Config impl: cuora.toml file (explicit path, env, ./, ~/.config)</td></tr><tr><td><code>cuora-deploy-cf</code></td><td>adapter</td><td>Deploy impl: push secret values to a Cloudflare account Secrets Store (write-only sink) via the CF API v4</td></tr><tr><td><code>cuora-identity</code></td><td>adapter</td><td>Identity port: where the age identity (master key) comes from — file, keyring, later sealed variants</td></tr><tr><td><code>cuora-identity-file</code></td><td>adapter</td><td>Identity impl: the ~/.config/cuora/identity.txt age keyfile (0600) — the headless/CI default</td></tr><tr><td><code>cuora-identity-keyring</code></td><td>adapter</td><td>Identity impl: the platform session secret store (secret-service / Keychain / Credential Manager) via keyring-core</td></tr><tr><td><code>cuora-notice</code></td><td>adapter</td><td>Process-wide UX notices — muted/replayed stderr notes that must not corrupt the cuora ui alternate screen</td></tr><tr><td><code>cuora-serve</code></td><td>adapter</td><td>cuora serve — the ndjson request/response IPC surface orchestrators embed, with the external policy-decision consult (P-005)</td></tr><tr><td><code>cuora-shell</code></td><td>adapter</td><td>Run a command in a working directory via bash -c — the generic shell-out helper</td></tr><tr><td><code>cuora-testkit</code></td><td>adapter</td><td>Vault conformance suite — every cuora-vault impl passes the same contract tests (fake values only)</td></tr><tr><td><code>cuora-tui</code></td><td>adapter</td><td>cuora — interactive vault TUI; a thin front-end over cuora-ops (phase 5 polish)</td></tr><tr><td><code>cuora-vault-age</code></td><td>adapter</td><td>Local vault impl: one age-x25519-encrypted JSON doc — the v1 default backend</td></tr><tr><td><code>cuora-vault-cached</code></td><td>adapter</td><td>Composite vault impl: read-through age-encrypted local cache in front of any backend (P-007)</td></tr><tr><td><code>cuora-vault-cf</code></td><td>adapter</td><td>Remote vault impl: self-hosted Cloudflare Worker + D1 holding per-secret age ciphertext — the Worker never sees plaintext</td></tr><tr><td><code>cuora</code></td><td>binary</td><td>cuora — secrets broker for agents: reference URIs, redaction, env-injection CLI</td></tr></tbody></table><h2 id="front-ends" tabindex="-1">Front-ends <a class="header-anchor" href="#front-ends" aria-label="Permalink to &quot;Front-ends&quot;">​</a></h2><ul><li><strong><code>cuora</code> (CLI)</strong> — clap verbs + <code>--json</code>/<code>manifest</code>/<code>schema</code> for machines; the agent interface.</li><li><strong><code>cuora ui</code> (TUI)</strong> — a read-only ratatui browser over the same ops; feature-gated (<code>--no-default-features</code> for a lean binary).</li><li><strong><code>cuora serve</code></strong> — ndjson IPC over the Vault port with an exec-driven <code>[serve.pdp]</code> policy-decision hook (ADR-0003); peregrin&#39;s embedding point.</li></ul><h2 id="boundary-—-secret-materialization-only" tabindex="-1">Boundary — secret materialization only <a class="header-anchor" href="#boundary-—-secret-materialization-only" aria-label="Permalink to &quot;Boundary — secret materialization only&quot;">​</a></h2><p>cuora owns refs, vaults, env injection, redaction, and the audit wire. Neighbors own theirs — see <a href="./boundaries.html">boundaries</a> for the full map.</p>',9)])])}const m=t(d,[["render",c]]);export{h as __pageData,m as default};
